#pragma once

#ifndef WINVER
#define WINVER 0x0601
#endif
#ifndef _WIN32_WINNT
#define _WIN32_WINNT 0x0601
#endif

// NOTE: NOMINMAX is deliberately NOT defined here, nor through the package
// preprocessor-macro property. Defining it project-wide removes the min/max
// macros that the Windows SDK Gdiplus headers (GdiplusTypes.h, SDK 10.0.18362)
// require, which breaks the host framework vol_bitmap.cpp. The bridge .cpp
// defines NOMINMAX for its own translation unit only; that is all OCCT needs.

#include <WinSock2.h>
#include <WS2tcpip.h>
#include <windows.h>
#include <cstdint>

